using System;
using System.IO;
using System.Diagnostics;
using System.Threading;
using System.Drawing;
using Newtonsoft.Json.Linq;
namespace JonsboStudio {
 static class TrimTests {
  static void Assert(bool value,string message){if(!value)throw new Exception("Video trim: "+message);}
  public static string MakeVideo(string folder){string video=Path.Combine(folder,"three colors.mp4");var info=new ProcessStartInfo(PlaybackEngine.Ffmpeg,"-hide_banner -loglevel error -f lavfi -i color=c=red:s=160x60:r=60:d=1 -f lavfi -i color=c=green:s=160x60:r=60:d=1 -f lavfi -i color=c=blue:s=160x60:r=60:d=1 -filter_complex \"[0:v][1:v][2:v]concat=n=3:v=1:a=0[out]\" -map \"[out]\" -c:v libopenh264 -b:v 1M -g 60 -pix_fmt yuv420p -an -y \""+video+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true};using(var process=Process.Start(info)){string error=process.StandardError.ReadToEnd();process.WaitForExit();Assert(process.ExitCode==0,"fixture generation failed: "+error);}return video;}
  public static void Run(){string folder=Path.Combine(AppPaths.Data("Temp"),"trim-"+Guid.NewGuid().ToString("N")),saved=null,imported=null;Directory.CreateDirectory(folder);try{
   var defaults=VideoTrim.Read(new JObject());Assert(defaults.Start==0&&!defaults.End.HasValue&&defaults.Duration(3)==3,"old themes must play the full video");
   foreach(var invalid in new[]{new JObject{{"VideoTrimStart",-1}},new JObject{{"VideoTrimStart",2},{"VideoTrimEnd",1}},new JObject{{"VideoTrimStart",1},{"VideoTrimEnd",1}},new JObject{{"VideoTrimStart",double.NaN}},new JObject{{"VideoTrimEnd","bad"}}}){try{VideoTrim.Read(invalid);throw new Exception("Invalid trim accepted");}catch(InvalidDataException){}}
   Assert(new VideoTrim{Start=1,End=99}.Duration(3)==2,"end beyond media must clamp to its duration");try{new VideoTrim{Start=3}.Duration(3);throw new Exception("Out-of-range start accepted");}catch(InvalidDataException){}
   string video=MakeVideo(folder);
   byte[] original=File.ReadAllBytes(video);var json=ThemeDocument.Blank("Trim test "+Guid.NewGuid().ToString("N"),160,60);json["BackgroundVideoFile"]=video;json["VideoTrimStart"]=1;json["VideoTrimEnd"]=2;saved=ThemeRepository.SaveEditor(json);var document=ThemeDocument.Load(saved);Assert(document.Trim.Start==1&&document.Trim.End==2,"save/reload must retain bounds");
   string archive=Path.Combine(folder,"trim.vmax");ThemeRepository.Export(saved,archive);imported=ThemeRepository.Import(archive);var copy=ThemeDocument.Load(imported);Assert(copy.Trim.Start==1&&copy.Trim.End==2&&File.Exists(copy.Background),"native export/import must retain trim and portable media");Assert(Convert.ToBase64String(original)==Convert.ToBase64String(File.ReadAllBytes(video)),"original media must stay unchanged");
   using(var engine=new PlaybackEngine(copy,new StudioSettings{Width=160,Height=60,Fps=60,Quality=75,CacheMB=32},false)){engine.Start();var watch=Stopwatch.StartNew();while(!engine.PreparedComplete&&engine.Error.Length==0&&watch.ElapsedMilliseconds<15000)Thread.Sleep(20);Assert(engine.Error.Length==0&&engine.PreparedComplete,"trim preparation failed: "+engine.Error);Assert(Math.Abs(engine.Duration-1)<.001&&engine.ExpectedFrames==60&&engine.Prepared==60,"only the selected 60-frame segment should be cached");watch.Restart();int samples=0;byte[] previous=null;while(watch.ElapsedMilliseconds<1400){var frame=engine.Latest;if(frame!=null&&!ReferenceEquals(frame.jpeg,previous)){previous=frame.jpeg;using(var stream=new MemoryStream(frame.jpeg))using(var bitmap=new Bitmap(stream)){var pixel=bitmap.GetPixel(80,30);Assert(pixel.G>70&&pixel.R<50&&pixel.B<50,"loop escaped the green middle segment");}samples++;}Thread.Sleep(5);}Assert(samples>30,"trimmed loop did not play smoothly");}
   copy.Json["VideoTrimStart"]=0;copy.Json["VideoTrimEnd"]=1;using(var engine=new PlaybackEngine(copy,new StudioSettings{Width=160,Height=60,Fps=60,Quality=75,CacheMB=32},false)){engine.Start();var timer=Stopwatch.StartNew();while((!engine.PreparedComplete||engine.Latest==null)&&engine.Error.Length==0&&timer.ElapsedMilliseconds<15000)Thread.Sleep(20);Assert(engine.Latest!=null&&engine.Error.Length==0,"changed trim failed to prepare");using(var stream=new MemoryStream(engine.Latest.jpeg))using(var bitmap=new Bitmap(stream)){var pixel=bitmap.GetPixel(80,30);Assert(pixel.R>140&&pixel.G<50&&pixel.B<50,"changing trim must not reuse the previous green cache");}}
   Console.WriteLine("PASS: trim validation, original-file preservation, native save/export/import, accurate seek and a 60-frame green-only loop from a red/green/blue video.");
  }finally{foreach(string path in new[]{imported,saved})if(path!=null&&Path.GetFullPath(path).StartsWith(Path.GetFullPath(AppPaths.Data("Themes"))+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))Directory.Delete(Path.GetDirectoryName(path),true);Directory.Delete(folder,true);}}
 }
}
